import type { AIProvider, ExtractionInput, QuestionExtraction, SolveInput, QuestionSolution, ValidationInput, ValidationResult, TopicClassificationInput, TopicClassification, ProviderName } from '../types.js';

export class OpenAIProvider implements AIProvider {
  name: ProviderName = 'openai';
  private apiKey: string;
  private model: string;
  constructor(apiKey?: string, model = 'gpt-4o') {
    this.apiKey = apiKey ?? '';
    this.model = model;
  }
  async extractQuestion(input: ExtractionInput): Promise<QuestionExtraction> {
    await new Promise((r) => setTimeout(r, 50));
    return { extractedText: 'What is the capital of France?', normalizedText: 'What is the capital of France?', detectedLanguage: 'en', questionType: 'multiple_choice', options: [{ label: 'A', value: 'Paris', order: 0 }, { label: 'B', value: 'London', order: 1 }, { label: 'C', value: 'Berlin', order: 2 }], confidence: 0.92 };
  }
  async solveQuestion(input: SolveInput): Promise<QuestionSolution> {
    await new Promise((r) => setTimeout(r, 100));
    return { shortAnswer: 'Paris', selectedOption: 0, fullExplanation: 'Paris is the capital of France.', reasoningSummary: 'Paris is the capital city of France.', confidenceScore: 0.94, validationStatus: 'not_validated' };
  }
  async validateAnswer(input: ValidationInput): Promise<ValidationResult> {
    await new Promise((r) => setTimeout(r, 50));
    return { status: 'pass', issues: [], confidenceAdjustment: 0 };
  }
  async classifyTopic(input: TopicClassificationInput): Promise<TopicClassification> {
    await new Promise((r) => setTimeout(r, 50));
    return { topic: 'Geography', confidence: 0.9 };
  }
}

